#!/usr/bin/env python3
"""
Round 111c (culprits), 29 September 2026. Needs round 110c.

Planted, bought or captured by country, per 100 seats, and more sources.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

DIFF = ''

NOTE = '## Round 111c (29 September)\n\nNeeds round 110c. Tiles patch round111c_tiles.py beside it.\n\n- capture_countries and capture_share (route country, beside capture_cases in\n  both places), read from tiles capture/by_country.json: cases per country by\n  the Natural Earth 50m shape each point falls in, split by tier and branch;\n  the legislature\'s seats today (Wikidata P194 -> P1342, or its chambers\'\n  sum); lawmakers found per 100 seats today. A case standing for many people\n  ("people in this case": Colombia 86, Japan LDP 179) counts as that many when\n  larger than the people found one by one.\n- capture.py also reads: secret-police collaborator categories on the lt, lv,\n  et, hu, sq, ru, uk, hr, sl, sr Wikipedias; development banks\' debarment lists\n  via OpenSanctions (index.json, datasets whose title/publisher name a bank and\n  a debarment; tier inquiry, CC BY-NC 4.0); FARA foreign principals (DOJ bulk\n  zip, tier ties, at the principal\'s country\'s capital).\n- Still to do: Czech ABS and Slovak UPN StB registers (waiting on\n  probe/capture/ from the first capture run).\n- Script version app.js?v=1003.\n\n'
HEAD = "## Round 111c (29 September)"

def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round111c: run from the culprits repository root")
    h = root / "HANDOFF.md"
    text = h.read_text(encoding="utf-8")
    if "## Round 110c" not in text:
        sys.exit("round111c: round 110c must be applied first")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", "--binary", path, check=False).returncode == 0:
        print("round111c: already applied")
    else:
        r = git("apply", "--3way", "--binary", path, check=False)
        if r.returncode != 0:
            sys.exit("round111c: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round111c: applied")
    text = h.read_text(encoding="utf-8")
    if HEAD not in text:
        at = text.index("## Round 110c")
        h.write_text(text[:at] + NOTE + text[at:], encoding="utf-8")


if __name__ == "__main__":
    main()
